Lemma flag_rel_sem : forall srcf cl c f' cj s E E' M, flag_rel srcf cl c f' (CC.esubstL NF s (reg_e cj 20)) = true -> env_agree (CC.cp_nx c) E E' -> know_ok segs E M (CC.cp_know c) ->
