(* [comment removed for export] *)
Lemma scx_facts : forall i c ps E R (M : word -> option byte) E' R' M',
  nth_error CPS i = Some c -> cut_chk i c = true -> scx_chk i c ps = true ->
  CC.At segs c E R M -> env_agree NF E0 E -> TV M -> XI i E M -> env_agree (CC.cp_nx c) E E' -> CC.leaf_facts segs c ps E' R' M M' -> TV M' ->
  (forall d, 0 <= d < N + 1 -> M' (Z_to_bv 64 (Q + d)) <> None) ->
  exists (k : Z) (ra : Z) (ja : nat) (cja cjb : CC.cutpoint),
    let P' := Q + N + 1 - k in let txe := skipn (Z.to_nat (N - k + 1)) txt in
    1 <= k <= N /\ Z.of_nat (length txe) = k - 1 /\
    D = (N - k) + match PD.exp_scan txe with Some k2 => 1 + k2 | None => 0 end /\
    PDC.rz R' 10 = F /\ PDC.rz R' 11 = 1 /\ PDC.rz R' 2 = SP /\ getr R' (PDC.reg_of 1) = Z_to_bv 64 ra /\ nth 1 (CA.ps_reglist ps) (ELit 1) = ELit ra /\ 0 <= ra < 2 ^ 47 /\ ra mod 2 = 0 /\
    L5.u64_at segs M' (F + 8) P' /\ L5.u64_at segs M' (F + 184) (2 ^ 64 - 1) /\ L5.u64_at segs M' (F + 192) 0 /\
    PDC.text_ok segs M' P' txe /\ kentry_ok segs E' M' (KImg IMG_LO IMG_HI) /\ CVF.all_regs_chk ps = true /\
    In (KRange (CC.cp_meas c) 1 CC.MB) (SR.ps_cells ps) /\ APC.expr_vars_lt (CC.cp_nx c) (CC.cp_meas c) = true /\
